import("stdfaust.lib");
process = par(i,2,expander) with {
    threshold = hslider("Threshold [unit:dB]", -40, -80, 0, 0.1) : si.smoo;
    ratio     = hslider("Ratio", 2.0, 1.0, 10.0, 0.01) : si.smoo;
    attack    = hslider("Attack [unit:ms]", 10, 0.1, 200, 0.1) : si.smoo;
    release   = hslider("Release [unit:ms]", 100, 1, 500, 1) : si.smoo;
    makeup    = hslider("Makeup Gain [unit:dB]", 0, -20, 20, 0.1) : si.smoo;
    env(x)    = an.amp_follower_ar(attack, release)(x);
    level(x)  = env(x) : ba.linear2db;
    gainDB(x) = select2(level(x) < threshold, 0, (threshold - level(x)) * (ratio - 1));
    totalGain(x) = (gainDB(x) + makeup) : ba.db2linear : si.smoo;
    expander(x) = x * totalGain(x);
};

import("stdfaust.lib");
comp(L,R,SC) = (Lout,Rout) with {
    thresh = hslider("Threshold [unit:dB]", -20, -60, 0, 0.1) : si.smoo;
    ratio  = hslider("Ratio", 4, 1, 20, 0.1);
    attMs  = hslider("Attack [unit:ms]", 10, 0.1, 200, 0.1) : si.smoo;
    relMs  = hslider("Release [unit:ms]", 100, 1, 500, 1) : si.smoo;
    att    = attMs * 0.001;
    rel    = relMs * 0.001;
    makeup = hslider("Makeup Gain [unit:dB]", 0, -12, 12, 0.1) : ba.db2linear : si.smoo;
    env    = SC : an.amp_follower_ar(att, rel) : si.smoo;
    gain_dB = select2(env > thresh, 0, -(env - thresh)*(1 - 1/ratio));
    gain_lin = gain_dB : ba.db2linear;
    Lout = L * gain_lin * makeup;
    Rout = R * gain_lin * makeup;
};
process = (L,R,SC) : comp;

